window.RP_SESSION={"id":"S-3a391c29dc43","messages":[{"id":"RP-III-0163104","time":"2026-09-02T23:23:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이곳은 동부의 어느 초원.","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163105","time":"2026-09-02T23:23:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"~~~","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163106","time":"2026-09-02T23:24:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 왔구만! 동료에게 들었다시피 확실하게 숨을 끊어놨으니깐 말이야, 혹시나 저번처럼 짐마차에서 갑자기 깨어나 난동을 부릴 일은 없을거라고.”","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163107","time":"2026-09-02T23:25:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“내 몫은 전에 말한 것 처럼 등가죽 부분의 모피 절반, 그리고 의뢰비는…\n아, 지금 주는거구만? 여이, 잘 받을게~”","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163108","time":"2026-09-02T23:26:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“읏차, 음… 하나 둘 셋…\n여이! 정확한걸. 저번에는 그쪽들이 조금 떼먹으려던걸 돌려받으려고 멱살도 잡고 한바탕 난리였었지~ 이번엔 안그래서 다행이네, 하하!“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163109","time":"2026-09-02T23:27:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”다음에도 좋은 의뢰 많이많이 보내주고 말이야, 잡는데에 고생 좀 했으니까 잘 다뤄달라고~“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163110","time":"2026-09-02T23:27:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”…음! 여이, 그쪽들도 조심히 들어가~“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163111","time":"2026-09-02T23:27:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”…“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163112","time":"2026-09-02T23:28:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”끄아아아~~~“\n\n허그는 크게 기지개를 한 번 켭니다.\n\n”이제 나도 그만 집으로 돌아가 보자고, 여이~!“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163113","time":"2026-09-02T23:29:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"말했다시피 이곳은 동부의 한 초원,\n가델랏 허그는 여느때와 같이 사냥 의뢰를 나섰습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163114","time":"2026-09-02T23:30:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이번 사냥감은 뿔이 무지하게 긴 털양, 녀석이 허그와 의뢰 동료들을 향해 맹렬히 들이받을 때마다 그렇게나 아찔하지 않을 수가 없었습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163115","time":"2026-09-02T23:31:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"일행들은 녀석의 공격 방식에 적응한 뒤, 구덩이 함정을 파 허그가 그 방향으로 유인하고, 철퇴로 녀석의 뿔을 걸어 목을 들어올린 후에, 마지막엔 동료 둘이서 일제히 녀석의 늘어난 목을 베어내며 멱을 끊어냈었습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163116","time":"2026-09-02T23:33:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"앞서 들었듯이 허그가 요구한 보수는 보수금의 2할에 녀석의 등가죽의 양털 절반을 더한 몫.\n처음부터, 허그가 이 의뢰를 수주한 이유는 오직 이 푹신하고도 거대한 양털에 있었습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163117","time":"2026-09-02T23:34:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그제 밤, 기숙사에서 사용하던 배게가 크게 찢어져버려 밤새 뒹구는 허그의 잠버릇에 따라 내부의 솜이 이리 저리 빠져나가 버렸었습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163118","time":"2026-09-02T23:36:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"두 뿔이 뒤통수에서 부터 눕듯이 뻗어 자라난 허그에게 있어 이 고약한 잠버릇은 상당한 골칫거리에 해당하죠.\n이렇게 쓰는 베개(배게가 아니었다고)가 뚫려 망가져버리거나, 이불이 눌리는 둥 불편한 일이 한 번씩 일어납니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163119","time":"2026-09-02T23:37:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그래도 그때마다, 우리의 손재주 좋은 허그는 뼈바늘과 얇은 가죽 끈 또는 마수의 실로 어느정도 나쁘지 않게 고쳐낼 수 있기에, 이번에도 허그는 베개를 직접 고쳐보려 합니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163120","time":"2026-09-02T23:38:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"그리고 그때...","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163121","time":"2026-09-02T23:38:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"속이 빠진 베개는 이번엔 멋들어진 고-급 양 마수의 털로 더 좋게 고쳐주고, 이참에 남는 솜으로는…","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163122","time":"2026-09-02T23:38:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"읭?","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163123","time":"2026-09-02T23:39:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"누군가 허그의 텐트로 다가오는 인기척이 들렸습니다.","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163124","time":"2026-09-02T23:39:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“흐흐흠… 엥?”","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163125","time":"2026-09-02T23:39:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"누구인가 누가 인기척을 내었어","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163126","time":"2026-09-02T23:41:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 아, 허그씨. 계세요? 나에요 나. '비론소'요. \"\n\n동료중 한명이었던 티플링 사내 비론소였습니다.","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163127","time":"2026-09-02T23:42:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“아, 여이! 난 또 누구인가 했네. 들어와~ 딱히 잠구는건 없어.”","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163128","time":"2026-09-02T23:42:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 전리품을 정리하다가, 텐트의 입구를 향해 말합니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163129","time":"2026-09-02T23:42:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"ㅌ","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163130","time":"2026-09-02T23:42:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 엇, 그, 그래도 되겠어요? \"\n\n그는 천막 입구를 들추며 헤실- 손인사를 했습니다.","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163131","time":"2026-09-02T23:42:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163132","time":"2026-09-02T23:43:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"샵검색: #삼각 텐트","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163133","time":"2026-09-02T23:44:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"요래 생겼을 것 같은데 아마 더 해진!","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163134","time":"2026-09-02T23:44:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"(헤진은 또 해진이 아니었다고)","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163135","time":"2026-09-02T23:44:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그도 손인사를 합니다~","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163136","time":"2026-09-02T23:45:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 밤늦게 죄송해요 허그씨. 다른 건 아니고... 아까 녀석과 싸울 때, 고마웠다구요. 왜, 그물망에 제 다리가 걸려버려서 위험했을 때요. 허그씨가 아니었음 정말 큰일 날 뻔했어요. \"\n\n그는 텐트 앞에 선 채 얘기를 이어갔습니다.","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163138","time":"2026-09-02T23:46:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“하하하, 아무래도 말이지. 그때 그쪽 꼴이 말이 아니었던거 알지? 막 허우적 허우적~\n하하, 덕분에 끄집어 내기 더 힘들었었다고.“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163139","time":"2026-09-02T23:48:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 특히 마지막에 허그씨가 녀석의 머리를 들어올리지 않았다면 해내지 못했을거에요. 우리도 지쳐가는 상황이었고 또... \"","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163140","time":"2026-09-02T23:49:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" ... 그거 아세요? \"\n\n비론소가 조용히 얘기 했습니다.\n\n\" 허그씨는... 굉장히 매력적인 여성이에요. \"","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163141","time":"2026-09-02T23:51:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…엥? 갑자기?”\n\n허그는 짐을 정리하다 말고 의아해합니다.\n\n“여이, 뭐… 아무래도 요즘의 나는 여러모로 노력을 많이 하고있으니깐 말이야. 챙겨야 하는 식구들도 있고, 아무래도 그거 때문에 더 멋들어져 보이는걸거라고?”","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163142","time":"2026-09-02T23:52:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그쪽도 아까 굉장했었어~ 팔 힘이 장난이 아니던데? 그 녀석 목을 콱~ 막 그랬었잖아.”","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163143","time":"2026-09-02T23:54:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 그렇죠. 사실 저도 놀랐어요. 이번 의뢰에서 허그씨가 우리 파티에 합류했을때요. 동족을 만난 것도 의외였지만, 이렇게 실력있는 분이 들어오실 줄은 몰랐어요.\n\n솔직히 말씀드리면... 어느 순간부터는, 허그씨가 계속 신경 쓰이더라구요. \"","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163144","time":"2026-09-02T23:56:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“헉.”\n\n“…”\n\n“여이… 내가 그정도로 불안했었나? 끄아, 이번엔 나름 열심히 했는데 말이야…\n아무래도 베테랑 사냥꾼까지는 아직 멀었나보는걸…“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163145","time":"2026-09-02T23:56:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"‘이번에도 뭔가 실수를 했나보는데…\n뭐지? 막 나가지도 않았었고 말이야, 나름 사람들 신경도 썼고 또…’","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163146","time":"2026-09-02T23:57:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 네... 불안... 했어요. \"\n\n비론소가 고개를 잠시 숙이며 뒷목을 작게 긁었습니다.\n\n그리곤 잠시 망설이듯 멈추어 말을 이어갔습니다.\n\n\" 허그씨가 다치시는 모습을... 보게 될까봐서요. \"","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163147","time":"2026-09-02T23:58:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“하하, 그렇게 걱정해주니 고마운걸.\n그래도 말이야, 사람 다치는게 무서우면 이쪽 일도 그리 오래는 못한다고? 원래 몸 쓰는 일들은 어떻게던 다치게 되있으니깐 말이지~”\n\n“읏차, 흣짜…“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163148","time":"2026-09-03T00:01:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"허그가 몸을 푸는 소리.\n\n달그락이는 그녀의 전리품.\n\n텐트의 천막에 바람이 스치우는 소리.\n\n그리고 짧은 정적.\n\n비론소는 조용히 고개를 들어 허그를 쳐다봤습니다.\n\n천막을 쥔 그의 손이 작게 떨립니다. \n\n\" ... 나... 허그씨 좋아해요. 그래서...  \"","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163149","time":"2026-09-03T00:02:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 그래, 그렇게 말해주니깐…”","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163150","time":"2026-09-03T00:02:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…”","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163151","time":"2026-09-03T00:02:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“……?”","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163152","time":"2026-09-03T00:02:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“엥?“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163153","time":"2026-09-03T00:03:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”하하, 아까 녀석 때문에 내가 아직도 귀가 울리는 건가, 다시 말해줄 수 있으려나~“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163154","time":"2026-09-03T00:03:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 동족으로써... 사냥꾼으로써가 아니라... 이성으로써 허그씨를 더 알아가보고 싶어요. \"","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163155","time":"2026-09-03T00:04:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“어…엥? 이성이라니, 친구로써 말하는거야? 나야 술친구라면 얼마든지 받아주기는 하는데 말이야…”","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163156","time":"2026-09-03T00:05:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“설마, 뭐 이상한 그런건 아니겠지 비론소씨?\n하하, 막 그런거 있잖아~ 요상한거 말이지.“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163157","time":"2026-09-03T00:07:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"허그의 대답에 비론소가 작게 웃었습니다.\n\n\" 그런 모습들요. 사냥감 앞에선 맹랑하고, 당차고. 씩씩하지만, 가끔 허그씨가 조용히 뭔갈 생각하는 모습을 봤어요.\n\n그래서 한 번 물어보고 싶어요.\n\n혹시... 좋아하는 분이 있으신가요? \"","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163158","time":"2026-09-03T00:09:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이… 뭔가 어째 점점 분위기를 잡으려고 그러는 것 같은데 말이야~ 이런 장난도 오랜만인걸.\n아무튼, 그거부터 얘기 해보자면야…“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163159","time":"2026-09-03T00:10:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”나야 없지, 당연하게도.“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163160","time":"2026-09-03T00:10:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”주위에는 전부 식구들이나 친한 친구들 뿐이니깐 말이야, 다들 믿고 도와주는 사이니 꼭 누구 하나를 좋아할 필요도 없고 말이지~“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163161","time":"2026-09-03T00:13:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 난 이번 여정을 같이 하면서... 어느 순간 허그씨가 계속 신경쓰였어요.\n\n그래서 드는 욕심일까...\n\n나도, 허그씨에게 조금은 신경쓰이는 사람이 되고 싶어요. \"","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163162","time":"2026-09-03T00:14:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 이성으로써요. \"","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163163","time":"2026-09-03T00:15:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 그런건가~\n확실히 말이야, 이번 사냥은 그래도 꽤나 즐거웠었지~ 다들 합도 착착! 잘 맞은데에다 서로 도와주면서 싸웠으니깐.\n원한다면 그쪽도 같ㅇ“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163164","time":"2026-09-03T00:15:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…”","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163165","time":"2026-09-03T00:17:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“아하이, 왜그러나 아까부터~\n비론소씨, 우리 사냥으로 만난지 이틀밖에 안됬다고?\n일때문에 유독 마음이 들떠버려서 비론소씨도 모르게 그런 말들이 나올 수도 있으니깐 말이야, 일단은 그 얘긴 접어두고 다음에 술이나 한 번 같이 드는게 차라리 어때?”","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163166","time":"2026-09-03T00:18:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그편이 훨씬 즐겁기도 하고, 아무래도 서로 편하니까.”","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163167","time":"2026-09-03T00:18:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“아, 혹시 술은 싫어할려나? 요즘따라 어째 술을 못마시는 녀석들을 자주 만나서 말이지.“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163168","time":"2026-09-03T00:19:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"페디안… 마리아… 베어… 킨… 뻬르난떼 경… 어쩌구…","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163169","time":"2026-09-03T00:20:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"비론소는 허그의 대답에 작은 쓴웃음을 지었습니다.\n\n\" 그렇게 말씀해주셔서 고마워요 허그씨. 역시 허그씨는 친절하시네요. \"\n\n그리곤 부랴부랴 천막을 쥔 손을 뗐습니다.\n\n\" 수, 술은 다음에 같이 마셔요. 오늘은... 아직 피로가 가시지 않았고... 또... 정리하실 것도 많으니까요. \"","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163170","time":"2026-09-03T00:20:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 정리하던 짐을 어째 조금 황급히 밀어넣고, 배낭 정리를 마무리 하기 시작합니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163171","time":"2026-09-03T00:21:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 고마운걸. 생각 잘했어, 아무래도 서로 지쳤을테니깐 말이야~”","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163172","time":"2026-09-03T00:22:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 그럼, 쉬세요. 밤 중에 실례했어요. \"","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163173","time":"2026-09-03T00:22:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여이, 나머지는 내일 같이 돌아가면서 얘기\n나누자고~“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163174","time":"2026-09-03T00:22:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”잘 들어가~!“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163175","time":"2026-09-03T00:22:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 손을 흔들며 인사합니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163176","time":"2026-09-03T00:23:00+09:00","room":"RP III","name":"비론소","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"-꾸벅.\n\n비론소도 짧은 목례와 함께 떠나갔습니다.","characters":["P-4c74603b91b9"]},{"id":"RP-III-0163177","time":"2026-09-03T00:23:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…”\n\n갔나","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163178","time":"2026-09-03T00:25:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“끄아~~~ 이런, 의뢰 끝난 날 밤에 서로 힘빠지게 왜 그런거야 비론소씨는.\n그냥 사이 좋게 술친구도 하고, 사냥 동료도 하면서 보로스 녀석처럼 오래오래 옆에서 지내면 될텐데 말이야.“","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163179","time":"2026-09-03T00:25:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 긴장이 살짝 풀린 듯 목소리에서 힘을 빼며 푸하…","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163180","time":"2026-09-03T00:26:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이런, 밤이 깊어가는군요!","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163181","time":"2026-09-03T00:27:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 망토와 갑옷을 벗어 갑옷은 배낭 옆에, 망토는 텐트 바닥에 깔아두고 그 위에서 잠을 청합니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163182","time":"2026-09-03T00:27:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"옆으로 누워서, 괜히 망토가 뚫리지 않게 말이죠~","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163183","time":"2026-09-03T00:32:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"낮이 될려나요?","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163184","time":"2026-09-03T00:42:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163185","time":"2026-09-03T00:44:00+09:00","room":"RP III","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"unresolved","type":"dialogue","body":"이모티콘","characters":[]},{"id":"RP-III-0163186","time":"2026-09-03T00:47:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"크아아아아앗 2부에서 계속~~~~","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163187","time":"2026-09-03T00:47:00+09:00","room":"RP III","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6a1a99e98a44"]},{"id":"RP-III-0163188","time":"2026-09-03T00:47:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
